##############################################################################
#
# Print REST service description
#
##############################################################################
print_about() {
    echo ""
    echo -e "${BOLD}${WHITE}Widgetic API Gateway command line client (API version 1.0.0)${OFF}"
    echo ""
    echo -e "License: Widgetic Integration License"
    echo -e "Contact: "
    echo ""
read -r -d '' appdescription <<EOF

API documentation for the Widgetic API Gateway
EOF
echo "$appdescription" | paste -sd' ' | fold -sw 80
}


##############################################################################
#
# Print REST api version
#
##############################################################################
print_version() {
    echo ""
    echo -e "${BOLD}Widgetic API Gateway command line client (API version 1.0.0)${OFF}"
    echo ""
}

