##############################################################################
#
# Print help for createCanvas_0 operation
#
##############################################################################
print_createCanvas_0_help() {
    echo ""
    echo -e "${BOLD}${WHITE}createCanvas_0 - Create Canvas${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Creates a new canvas with the specified properties.

To make the canvas for one of your managed users, send 'managedUserId' or 'managedUserExternalId'. The canvas
stays in your account and is yours to edit; the tag lets you list one user's canvases with 'getAllCanvases'.
The managed user must be yours and active: one that is not yours, or does not exist, is answered with 404 and
'MANAGED_USER_NOT_FOUND', and one that is switched off with 409 and 'MANAGED_USER_INACTIVE'. The tag is set
here and does not change afterwards. Called with an editor session, the canvas is always made for the
session's managed user." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}body${OFF} ${BLUE}[application/json]${OFF} ${RED}(required)${OFF}${OFF} - " | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=201
    echo -e "${result_color_table[${code:0:1}]}  201;Canvas created successfully${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;Invalid input (for example a 'managedUserId' that is not a UUID, or both 'managedUserId' and 'managedUserExternalId').${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;Unauthorized${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;The managed user named by 'managedUserId' or 'managedUserExternalId' is not one of yours ('MANAGED_USER_NOT_FOUND').${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=409
    echo -e "${result_color_table[${code:0:1}]}  409;The managed user is switched off, so nothing new can be made for it ('MANAGED_USER_INACTIVE').${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
