    echo ""
    echo -e "${BOLD}${WHITE}setDynamicContent_0 - Set Dynamic Content${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
