print_deleteCompositionDatabaseRecord_help() {
    echo ""
    echo -e "${BOLD}${WHITE}deleteCompositionDatabaseRecord - Delete Record From Composition Database${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Deletes a specific record from one of the composition's tables. Only the composition's own tables (made from its 'databaseSchema' or from the tables its widget declares) can be reached; any other table name answers '404'." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}id${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - ID of the composition ${YELLOW}Specify as: id=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
