    echo ""
    echo -e "${BOLD}${WHITE}describeCompositionEntries - Describe What a Composition Keeps${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
