##############################################################################
#
# Print help for exportCompositionEntryItems operation
#
##############################################################################
print_exportCompositionEntryItems_help() {
    echo ""
    echo -e "${BOLD}${WHITE}exportCompositionEntryItems - Export composition entry items${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Streams up to 50,000 matching rows in batches of 1,000. Tables without cursor paging export at most one batch; when more rows exist the response sets 'X-Widgetic-Export-Truncated: true'. Rate limit 20 requests per minute." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}id${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} -  ${YELLOW}Specify as: id=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}table${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} -  ${YELLOW}Specify as: table=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}format${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: csv)${OFF} - ${YELLOW} Specify as: format=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}order${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: desc)${OFF} - 'desc' (the default) lists the newest entry first, 'asc' the oldest. Entries are sorted by their time, then
by their id (compared as text, byte by byte) in the same direction, so the order of two entries made at the
same instant is always the same; an entry with no time counts as the oldest. A table with no time column is
sorted by its id. The managed-user feed sorts by time, then by composition id, table and id.${YELLOW} Specify as: order=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}since${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Only entries made at this time or later: 'since' is INCLUSIVE (an entry made at exactly 'since' is
returned). A date and time with an offset, such as '2026-10-01T00:00:00Z'; anything else answers 400
'INVALID_SINCE'. An entry with no time never matches, and a table with no time column answers 400
'ENTRY_TABLE_HAS_NO_TIME'.${YELLOW} Specify as: since=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}until${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Only entries made before this time: 'until' is EXCLUSIVE (an entry made at exactly 'until' is NOT
returned), so 'since=A&until=B' followed by 'since=B&until=C' counts every entry once. Same form and same
refusals as 'since' (400 'INVALID_UNTIL').${YELLOW} Specify as: until=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}context${OFF} ${BLUE}[map[String, string]]${OFF} ${CYAN}(default: null)${OFF} - Host context filters as 'context[key]=value' (max 5 keys, counting dotted 'context.key' too). Use 'column.<name>=value' for columns whose names collide with reserved parameters.${YELLOW} Specify as: ${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}filter${OFF} ${BLUE}[map[String, string]]${OFF} ${CYAN}(default: null)${OFF} - Column filters as 'filter[columnName]=value' (same meaning as bare 'columnName=value' or 'column.columnName=value'; max 10 column filters counting all spellings). A plain 'filter=value' still filters a column named 'filter'.${YELLOW} Specify as: ${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}X-Managed-User-Id${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - The id Widgetic gave the managed user ('POST /managed-users'). Makes this call for one of your managed users, so that a mistake in your own code cannot reach another customer's work. Send this header, or the other one, never both. Left out, the call works on your whole account, as it always has. With it, the call reaches only that user's compositions and workflows: a list shows only theirs, a composition or a workflow the call makes is filed under them, and one of another user, or one that does not exist, answers '404' (the same answer, so the call cannot be used to find out what another customer has). A managed user that is not yours answers '404' with 'MANAGED_USER_NOT_FOUND'. An empty, repeated or malformed header is '400' with 'MANAGED_USER_SCOPE_INVALID'; an empty header is never read as no header. A call that is about the whole account, such as the list of your managed users, is refused with '403' and 'MANAGED_USER_SCOPE_ROUTE_NOT_AVAILABLE': send it without the header. Only your API key can send it. The header is a limit the call asks for: whoever holds the key can leave it out, so for a credential that a customer's browser holds, use an editor session. An 'Idempotency-Key' is kept apart for each managed user. ${YELLOW}Specify as: X-Managed-User-Id:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}X-Managed-User-External-Id${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Your own id for the managed user (its 'externalId'), when you do not keep Widgetic's. Makes this call for one of your managed users, so that a mistake in your own code cannot reach another customer's work. Send this header, or the other one, never both. Left out, the call works on your whole account, as it always has. With it, the call reaches only that user's compositions and workflows: a list shows only theirs, a composition or a workflow the call makes is filed under them, and one of another user, or one that does not exist, answers '404' (the same answer, so the call cannot be used to find out what another customer has). A managed user that is not yours answers '404' with 'MANAGED_USER_NOT_FOUND'. An empty, repeated or malformed header is '400' with 'MANAGED_USER_SCOPE_INVALID'; an empty header is never read as no header. A call that is about the whole account, such as the list of your managed users, is refused with '403' and 'MANAGED_USER_SCOPE_ROUTE_NOT_AVAILABLE': send it without the header. Only your API key can send it. The header is a limit the call asks for: whoever holds the key can leave it out, so for a credential that a customer's browser holds, use an editor session. An 'Idempotency-Key' is kept apart for each managed user. ${YELLOW}Specify as: X-Managed-User-External-Id:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;Exported CSV or JSON stream${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
        echo -e "       ${BOLD}${WHITE}Response headers${OFF}"
        echo -e "       ${BLUE}X-Widgetic-Export-Truncated${OFF} - " | paste -sd' ' | fold -sw 80 | sed '2,$s/^/        /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;Invalid filters or parameters${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;Unauthorized${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;Caller cannot read this composition${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;Unknown table${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=429
    echo -e "${result_color_table[${code:0:1}]}  429;Rate limit exceeded${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
