##############################################################################
#
# Print help for getAllCanvases operation
#
##############################################################################
print_getAllCanvases_help() {
    echo ""
    echo -e "${BOLD}${WHITE}getAllCanvases - Get All Canvases${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Retrieves all canvases with pagination support and filtering options.

Pass 'managedUserId' (Widgetic's id for one of your managed users) or 'managedUserExternalId' (your own
identifier for the user) to list only the canvases made for that managed user. The canvases of your other
managed users, and your own, are left out. A managed user that is not yours, or does not exist, is answered
with 404 and 'MANAGED_USER_NOT_FOUND'. Called with an editor session, the list is always the session's
managed user's." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}page${OFF} ${BLUE}[integer]${OFF} ${CYAN}(default: 1)${OFF} - Page number for pagination${YELLOW} Specify as: page=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}size${OFF} ${BLUE}[integer]${OFF} ${CYAN}(default: 20)${OFF} - Number of items per page${YELLOW} Specify as: size=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}sort${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: created_at:desc)${OFF} - Sort field and direction (e.g., \"created_at:desc\")${YELLOW} Specify as: sort=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}createdAfter${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Filter canvases created after the specified date (ISO 8601 format)${YELLOW} Specify as: createdAfter=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}createdBefore${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Filter canvases created before the specified date (ISO 8601 format)${YELLOW} Specify as: createdBefore=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}updatedAfter${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Filter canvases updated after the specified date (ISO 8601 format)${YELLOW} Specify as: updatedAfter=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}updatedBefore${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Filter canvases updated before the specified date (ISO 8601 format)${YELLOW} Specify as: updatedBefore=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}managedUserId${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - List only the canvases made for this managed user (Widgetic's id for the user). Send this or 'managedUserExternalId', not both.${YELLOW} Specify as: managedUserId=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}managedUserExternalId${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - List only the canvases made for the managed user you registered with this 'externalId' (your own identifier for the user). Send this or 'managedUserId', not both.${YELLOW} Specify as: managedUserExternalId=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;List of canvases retrieved successfully${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;A parameter is not valid (for example a 'managedUserId' that is not a UUID, or both 'managedUserId' and 'managedUserExternalId').${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;Unauthorized${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;The managed user named by 'managedUserId' or 'managedUserExternalId' is not one of yours ('MANAGED_USER_NOT_FOUND').${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
