print_getUserApiKeys_help() {
    echo ""
    echo -e "${BOLD}${WHITE}getUserApiKeys - List the API keys of an account${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Lists the API keys of an account, in the order they were made: name, the first characters of the key, when it was made, when it expires, when it was last used, whether it is switched on and what it is limited to ('scopes' and 'preset'). The secret of a key is never part of the list. A caller can list its own account's keys; Widgetic staff can list any account's." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}id${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The account the keys belong to. For your own keys, your own user id ${YELLOW}Specify as: id=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;The keys of the account (an empty list for an account with none)${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;The account id is not a valid id${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;Not authenticated${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;The keys belong to another account${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for getUserCreditBalance operation
#
##############################################################################
print_getUserCreditBalance_help() {
    echo ""
    echo -e "${BOLD}${WHITE}getUserCreditBalance - Get an account's credit balance${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Returns the credits an account holds: the balance, and how much of it is reserved by operations that
are still running.

An account reads its own balance; with a partner's API key, that is the account of the person who
administers the partner. Widgetic administrators can read any account's. An account that has never held
credits reads a balance of 0. 'getPartnerCreditBalance' reads this same balance by partner id." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}userId${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The account whose balance to read ${YELLOW}Specify as: userId=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;The account's credit balance${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;The API key is missing or invalid${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;The balance belongs to another account${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;Credit balance not found${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for getUserCreditTransactions operation
#
##############################################################################
print_getUserCreditTransactions_help() {
    echo ""
    echo -e "${BOLD}${WHITE}getUserCreditTransactions - List an account's credit ledger${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Lists the entries of an account's credit ledger, newest first. This is also how an account's usage is
read: every operation that spends credits is a 'debit' entry, so summing the 'debit' entries over a
period gives the credits consumed in it, and the other types give what was added.

An account reads its own ledger; with a partner's API key, that is the account of the person who
administers the partner. Widgetic administrators can read any account's. 'getPartnerCreditTransactions'
reads this same ledger by partner id.

The page is always bounded: 'limit' defaults to 100 and is capped at 500, 'offset' defaults to 0." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}userId${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The account whose ledger to read ${YELLOW}Specify as: userId=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}transactionType${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Only entries of this type, for instance 'debit' for the credits spent. The types are listed on 'AccountCreditTransaction'.${YELLOW} Specify as: transactionType=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}limit${OFF} ${BLUE}[integer]${OFF} ${CYAN}(default: 100)${OFF} - Maximum number of entries to return${YELLOW} Specify as: limit=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}offset${OFF} ${BLUE}[integer]${OFF} ${CYAN}(default: 0)${OFF} - Number of entries to skip${YELLOW} Specify as: offset=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;The account's ledger entries, newest first${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;The API key is missing or invalid${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;The ledger belongs to another account${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for getWidgets operation
#
##############################################################################
print_getWidgets_help() {
    echo ""
    echo -e "${BOLD}${WHITE}getWidgets - List Widgets${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Lists the widgets your account owns, newest first. A widget is the reusable piece a composition is made
from; this is your own library, not a catalogue of Widgetic's widgets.

Pass 'page' (counting from 1) and 'size' (1 to 100, 20 when left out) to read the list one page at a time.
'meta' then carries 'total', 'hasNextPage' and 'hasPreviousPage', so a client can walk the list to its end.
A page past the end is an empty list. Without 'page' and 'size' the call returns the whole list in one
response, which only suits an account with a few widgets.

Pass 'canvasId' to list only the widgets on one of your canvases. That list is always returned whole,
whatever 'page' and 'size' say.

Pass 'managedUserId' (Widgetic's id for one of your managed users) or 'managedUserExternalId' (your own
identifier for the user) to list only the widgets made for that managed user. The widgets of your other
managed users, and your own, are left out. It combines with 'page', 'size' and 'canvasId'. A managed user
that is not yours, or does not exist, is answered with 404 and 'MANAGED_USER_NOT_FOUND'." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}page${OFF} ${BLUE}[integer]${OFF} ${CYAN}(default: null)${OFF} - Page to return, counting from 1. Giving 'page' or 'size' turns paging on.${YELLOW} Specify as: page=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}size${OFF} ${BLUE}[integer]${OFF} ${CYAN}(default: null)${OFF} - How many widgets a page holds (20 when 'page' is given without it). Giving 'page' or 'size' turns paging on.${YELLOW} Specify as: size=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}canvasId${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - List only the widgets on this canvas. The list is returned whole.${YELLOW} Specify as: canvasId=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}managedUserId${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - List only the widgets made for this managed user (Widgetic's id for the user). Send this or 'managedUserExternalId', not both.${YELLOW} Specify as: managedUserId=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}managedUserExternalId${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - List only the widgets made for the managed user you registered with this 'externalId' (your own identifier for the user). Send this or 'managedUserId', not both.${YELLOW} Specify as: managedUserExternalId=value${OFF}" \
        | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;List of widgets${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;A parameter is not valid (for example 'size' above 100, a 'canvasId' or 'managedUserId' that is not a UUID, or both 'managedUserId' and 'managedUserExternalId').${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;Unauthorized${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;The key's role may not use this endpoint.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;The managed user named by 'managedUserId' or 'managedUserExternalId' is not one of yours ('MANAGED_USER_NOT_FOUND').${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=429
    echo -e "${result_color_table[${code:0:1}]}  429;Too many requests. See the Retry-After header.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
