##############################################################################
#
# Print help for revokeManagedUserEditorSession operation
#
##############################################################################
print_revokeManagedUserEditorSession_help() {
    echo ""
    echo -e "${BOLD}${WHITE}revokeManagedUserEditorSession - End one editor session of a managed user${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Ends the session at once: its token stops working on the next request (on another server of ours, within
a few seconds). Ending a session that has already ended is fine." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}id${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The managed user the session is for ${YELLOW}Specify as: id=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}sessionId${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The 'sessionId' of the session, from 'createManagedUserEditorSession' ${YELLOW}Specify as: sessionId=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;The session has ended${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;Unauthorized${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;Forbidden - the caller is not a partner${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;No such managed user on your account ('MANAGED_USER_NOT_FOUND'), or no such session for it ('EDITOR_SESSION_NOT_FOUND')${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for revokeManagedUserEditorSessions operation
#
##############################################################################
print_revokeManagedUserEditorSessions_help() {
    echo ""
    echo -e "${BOLD}${WHITE}revokeManagedUserEditorSessions - End every editor session of a managed user${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Ends all of the managed user's live editor sessions at once, for example when the user signs out of your
platform. Their tokens stop working on the next request (on another server of ours, within a few seconds).
It is fine to call it for a user who has none." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}id${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The managed user whose sessions end ${YELLOW}Specify as: id=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;How many live sessions were ended${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;Unauthorized${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;Forbidden - the caller is not a partner${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;No such managed user on your account ('MANAGED_USER_NOT_FOUND')${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for rotatePartnerEntryContextSecret operation
#
##############################################################################
print_rotatePartnerEntryContextSecret_help() {
    echo ""
    echo -e "${BOLD}${WHITE}rotatePartnerEntryContextSecret - Make a secret to sign the context of your embeds${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Makes a secret to sign the 'context' of your embeds with, and returns it in 'secret': **keep it now, it is
shown once** and cannot be read again. Keep it on your server only: whoever holds it can write contexts your
compositions accept. Call this again to make a new secret; the one it replaces is still accepted for a day, so
that your server can switch without an entry being refused (making another within that day ends the overlap
with the first).

**What signing is for.** '<widgetic composition-id=\"...\" context='{\"customerId\":\"c_42\"}'>' hands attribution to
a widget, which sends it with every entry it saves. The page is yours but the browser is the visitor's:
anybody can change that attribute and file an entry under another customer's id. When your server signs the
context, the gateway refuses an entry whose context was changed, and the entries you keep hold attribution
your server wrote.

**How to sign** (on your server, for each page you render):

1. Take the context to give the widget. It may hold text and whole numbers only (within ±2^53, written without
   a fraction or an exponent).
2. Choose when the signature stops being good: 'widgetic_exp', in seconds since 1970 (UTC), no more than
   seven days from now. A minute of difference between clocks is forgiven.
3. Write the text to sign, with no spaces except those inside values:
   'widgetic-context.v1.<compositionId>.<widgetic_exp>.<json>'. '<compositionId>' is the id of the composition
   in lower case. '<json>' is the context as JSON with the keys in character-code order (so 'Z' comes before
   'a', and '10' before '9'), no spaces, strings escaped as JSON escapes them, and the two keys of the
   signature left out.
4. Sign that text: HMAC-SHA256 with the 32 bytes the secret stands for (the base64 text after 'ctxsec_'), and
   write the result as base64url without padding.
5. Give the widget the context with two keys added: 'widgetic_exp' and 'widgetic_sig' (the signature). The whole
   attribute, the two keys included, stays within the limits of any context: at most 20 keys, 2048 bytes of
   JSON, strings up to 500 characters. The two keys take two of the 20 keys and 87 bytes of the 2048.

A test vector, to check your code against before you rely on it. Secret
'ctxsec_AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8=' (the bytes 0 to 31), composition
'7c9e6679-7425-40de-944b-e07fc1f90ae7', 'widgetic_exp' 1792000000 and context
'{\"customerId\":\"c_42\",\"plan\":\"pro\",\"seats\":3}' sign the text
'widgetic-context.v1.7c9e6679-7425-40de-944b-e07fc1f90ae7.1792000000.{\"customerId\":\"c_42\",\"plan\":\"pro\",\"seats\":3}'
and give the signature 'j6g7151F54tl9C8oEY9levaYSppHME4fAPZ7WPwL8C8'. (The secret is the example's, not a
real one.)

**What the gateway does with an entry.** When you have a secret, an entry whose context carries a signature is
checked: a signature that does not match is refused with 403 'CONTEXT_SIGNATURE_INVALID', and one that is past
'widgetic_exp' with 403 'CONTEXT_SIGNATURE_EXPIRED'. When you also require signatures
('updatePartnerEntryContextSigning') an entry whose context carries none is refused with 403
'CONTEXT_SIGNATURE_REQUIRED'. The two keys are taken out before the entry is stored or announced: your entries
and your 'entry.created' events hold the context you wrote. A change you make reaches every part of the
gateway within a minute.

**What it does not do.** A signed context that has been seen (a page's source is public) can be sent again by
anyone until 'widgetic_exp'; when you must not accept the same context twice, put a value that is new for each
page view in it (a 'submissionId' you made up) and keep the ones you have seen. The signature covers the
entries that reach Widgetic's gateway: a row that gets into a table another way (your own code writing
straight into a database you brought, or the record calls of the composition's owner) does not pass
through it, and carries no context.

Retry this call with the same 'Idempotency-Key' if its answer was lost: the answer, secret included, is then
given again, and no second secret is made. This needs an API key with full access. The caller must be the
person who administers the partner, or a Widgetic administrator." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}partnerId${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The partner whose secret to make ${YELLOW}Specify as: partnerId=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}Idempotency-Key${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - Required: a call without it is refused with '400'. A key of your own that names this one request; a UUID is ideal. It is 8 to 50 characters of letters, digits, '-' and '_'. Send the same key again when you retry (after a timeout, a dropped connection or a '5xx') and the call is carried out once: the retry gets the first answer back, marked 'X-Idempotency-Cached: true'. The same key with a different body is refused with '422', and a retry that arrives while the first call is still running with '409' (see 'Retry-After'). ${YELLOW}Specify as: Idempotency-Key:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;The new secret, and how your signing stands now${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;The 'Idempotency-Key' header is missing${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;The API key is missing or invalid${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;The caller does not administer this partner, or the API key has not full access${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;There is no such partner (reported to administrators only)${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=429
    echo -e "${result_color_table[${code:0:1}]}  429;Too many changes in a short time. Try again after the Retry-After seconds.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=503
    echo -e "${result_color_table[${code:0:1}]}  503;Signed context is not available on this server right now (ENTRY_CONTEXT_SIGNING_UNAVAILABLE). Nothing was changed.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for rotatePartnerWebhookSecret operation
#
##############################################################################
print_rotatePartnerWebhookSecret_help() {
    echo ""
    echo -e "${BOLD}${WHITE}rotatePartnerWebhookSecret - Make a new secret for your webhook${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Makes a new secret to sign your webhook with, and returns it in 'webhookSecret': **keep it now, it is shown
once** and cannot be read again. Use it when the secret was lost, or may have leaked.

The secret you had keeps signing beside the new one for a day, so that your receiver can switch without a
call being rejected: during that day each call carries two signatures (see 'updatePartnerNotificationSettings'
for how they are verified). Rotating again within the day ends the overlap with the first secret.

Retry this call with the same 'Idempotency-Key' if its answer was lost: the answer, secret included, is then
given again, and no second secret is made.

This needs an API key with full access. The caller must be the person who administers the partner, or a
Widgetic administrator." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}partnerId${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The partner whose webhook secret to replace ${YELLOW}Specify as: partnerId=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}Idempotency-Key${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - Required: a call without it is refused with '400'. A key of your own that names this one request; a UUID is ideal. It is 8 to 50 characters of letters, digits, '-' and '_'. Send the same key again when you retry (after a timeout, a dropped connection or a '5xx') and the call is carried out once: the retry gets the first answer back, marked 'X-Idempotency-Cached: true'. The same key with a different body is refused with '422', and a retry that arrives while the first call is still running with '409' (see 'Retry-After'). ${YELLOW}Specify as: Idempotency-Key:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;The new secret, and the settings${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;The 'Idempotency-Key' header is missing${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;The API key is missing or invalid${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;The caller does not administer this partner, or the API key has not full access${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;There is no such partner (reported to administrators only)${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=429
    echo -e "${result_color_table[${code:0:1}]}  429;Too many changes in a short time. Try again after the Retry-After seconds.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=503
    echo -e "${result_color_table[${code:0:1}]}  503;Webhooks cannot be set up on this server right now (WEBHOOK_SIGNING_UNAVAILABLE). Nothing was changed.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for saveWorkspaceWorkflow operation
#
##############################################################################
print_saveWorkspaceWorkflow_help() {
    echo ""
    echo -e "${BOLD}${WHITE}saveWorkspaceWorkflow - Save the Draft of a Workflow${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Saves the name, the time zone and/or the graph of the draft. Send at least one. The save names the 'revision' the
editor started from and is refused with 409 ('BUSINESS_STATE_CONFLICT') when the draft has moved on, so two
people editing do not overwrite each other without knowing; read the workflow again and apply the change to it.
A save is never refused for what is wrong with the graph (a block with no connection yet is normal in a draft):
only the shape is judged here, and what stops a workflow going live is told when it is published. A graph larger
than 200,000 bytes, or with more than 100 blocks or 300 connections, is refused.
An archived workflow cannot be saved. Saving a live workflow changes the draft only: visitors keep getting the
published version until the changes are published.
For personal workspace, use 'personal' as workspaceId.
For organization workspace, use the organization UUID as workspaceId. Any active member can save." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}workspaceId${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The workspace: 'personal' for your own workspace, or the UUID of an organization. A call made for one of your
managed users ('X-Managed-User-Id') always uses 'personal': a managed user has no other workspace, and a call
that names an organization is refused with 403. ${YELLOW}Specify as: workspaceId=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}workflowId${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The workflow's id ${YELLOW}Specify as: workflowId=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}X-Managed-User-Id${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - The id Widgetic gave the managed user ('POST /managed-users'). Makes this call for one of your managed users, so that a mistake in your own code cannot reach another customer's work. Send this header, or the other one, never both. Left out, the call works on your whole account, as it always has. With it, the call reaches only that user's compositions and workflows: a list shows only theirs, a composition or a workflow the call makes is filed under them, and one of another user, or one that does not exist, answers '404' (the same answer, so the call cannot be used to find out what another customer has). A managed user that is not yours answers '404' with 'MANAGED_USER_NOT_FOUND'. An empty, repeated or malformed header is '400' with 'MANAGED_USER_SCOPE_INVALID'; an empty header is never read as no header. A call that is about the whole account, such as the list of your managed users, is refused with '403' and 'MANAGED_USER_SCOPE_ROUTE_NOT_AVAILABLE': send it without the header. Only your API key can send it. The header is a limit the call asks for: whoever holds the key can leave it out, so for a credential that a customer's browser holds, use an editor session. An 'Idempotency-Key' is kept apart for each managed user. ${YELLOW}Specify as: X-Managed-User-Id:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}X-Managed-User-External-Id${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Your own id for the managed user (its 'externalId'), when you do not keep Widgetic's. Makes this call for one of your managed users, so that a mistake in your own code cannot reach another customer's work. Send this header, or the other one, never both. Left out, the call works on your whole account, as it always has. With it, the call reaches only that user's compositions and workflows: a list shows only theirs, a composition or a workflow the call makes is filed under them, and one of another user, or one that does not exist, answers '404' (the same answer, so the call cannot be used to find out what another customer has). A managed user that is not yours answers '404' with 'MANAGED_USER_NOT_FOUND'. An empty, repeated or malformed header is '400' with 'MANAGED_USER_SCOPE_INVALID'; an empty header is never read as no header. A call that is about the whole account, such as the list of your managed users, is refused with '403' and 'MANAGED_USER_SCOPE_ROUTE_NOT_AVAILABLE': send it without the header. Only your API key can send it. The header is a limit the call asks for: whoever holds the key can leave it out, so for a credential that a customer's browser holds, use an editor session. An 'Idempotency-Key' is kept apart for each managed user. ${YELLOW}Specify as: X-Managed-User-External-Id:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}body${OFF} ${BLUE}[application/json]${OFF} ${RED}(required)${OFF}${OFF} - " | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;The draft was saved; the answer is the workflow without its graph (its new 'revision' is in it)${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;Nothing to save, or the name, the time zone or the shape of the graph is not acceptable${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;Unauthorized${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;Forbidden - Not a member of this organization, the plan does not include workflows ('AUTHZ_PLAN_RESTRICTION'), or the call is made for one managed user ('X-Managed-User-Id') in a workspace other than 'personal' ('MANAGED_USER_SCOPE_ROUTE_NOT_AVAILABLE')${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;No such workflow in this workspace${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=409
    echo -e "${result_color_table[${code:0:1}]}  409;The draft changed since 'revision' (BUSINESS_STATE_CONFLICT; 'details.reason' is 'revision_changed'), or the
workflow is archived. Nothing is overwritten. 'details.currentRevision' is the revision to start again from,
and for a workflow of an organization workspace 'details.lastEditedBy' ('{ id, name }', or 'null') and
'details.lastEditedAt' say who saved first and when.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=503
    echo -e "${result_color_table[${code:0:1}]}  503;Workflows cannot be used on this server right now${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for sendPartnerNotificationTestEvent operation
#
##############################################################################
print_sendPartnerNotificationTestEvent_help() {
    echo ""
    echo -e "${BOLD}${WHITE}sendPartnerNotificationTestEvent - Send a test event to your webhook${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Sends ONE signed call, right now, to the webhook address you saved under notification settings, with a sample
of what an event of the type you name carries, and answers how it went: whether your receiver answered with a
2xx status, which status, how long it took, and why not when it did not arrive. Use it to write and try your
receiver (above all the signature check) before a real event happens.

The call is made like every other: it is signed with your current secret (and the previous one while a
rotation overlaps), it carries the headers 'webhook-id', 'webhook-timestamp', 'webhook-signature' and
'x-widgetic-event' (the event type), and its body is '{ \"id\", \"type\", \"createdAt\", \"partnerId\", \"data\" }'.
Three things differ. 'id' starts with 'evt_test_' and is new every time, so a receiver that remembers ids can
tell a test from an event and drop it. 'data' holds made-up values of the shape a real event of that type
carries ('PartnerNotification' describes each), never anything about your account. And the call is made once:
it is not tried again, nothing is stored, and it appears neither in the delivery log nor in the notification
list.

It is sent whatever 'webhookEvents' says: a test is not filtered by what you subscribed to. The answer is 200
whether or not your receiver took the call (read 'delivered'); a call that gets no answer within ten seconds
is given up and reported as a 'timeout'.

A webhook address and a signing secret must be saved first ('updatePartnerNotificationSettings'); until then
the answer is 409. This needs an API key with full access, and 'Idempotency-Key' is required: a retry with the
same key gets the first answer back and no second call is made. The caller must be the person who
administers the partner, or a Widgetic administrator. Five tests a minute." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}partnerId${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - The partner whose webhook to try ${YELLOW}Specify as: partnerId=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}Idempotency-Key${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - Required: a call without it is refused with '400'. A key of your own that names this one request; a UUID is ideal. It is 8 to 50 characters of letters, digits, '-' and '_'. Send the same key again when you retry (after a timeout, a dropped connection or a '5xx') and the call is carried out once: the retry gets the first answer back, marked 'X-Idempotency-Cached: true'. The same key with a different body is refused with '422', and a retry that arrives while the first call is still running with '409' (see 'Retry-After'). ${YELLOW}Specify as: Idempotency-Key:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}body${OFF} ${BLUE}[application/json]${OFF} ${RED}(required)${OFF}${OFF} - " | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;The test call was made. 'delivered' says whether your receiver took it.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;'eventType' is missing or is not one of the events, or the 'Idempotency-Key' header is missing. Nothing was sent.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;The API key is missing or invalid${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;The caller does not administer this partner, or the API key has not full access${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;There is no such partner (reported to administrators only)${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=409
    echo -e "${result_color_table[${code:0:1}]}  409;The test cannot be sent now (BUSINESS_STATE_CONFLICT): no webhook address or no signing secret is saved yet. Nothing was sent.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=429
    echo -e "${result_color_table[${code:0:1}]}  429;Too many tests in a short time. Try again after the Retry-After seconds.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for setCompositionDataSource operation
#
##############################################################################
print_setCompositionDataSource_help() {
    echo ""
    echo -e "${BOLD}${WHITE}setCompositionDataSource - Bind a public JSON data source for embed refresh${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Stores an https URL the widget runtime may read on load and every 'refreshSeconds'. The URL must name a public host (no loopback, link-local or metadata addresses). A composition has one binding: saving another replaces it. The answer is the binding as it was saved ('url', 'refreshSeconds')." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}id${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} -  ${YELLOW}Specify as: id=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}Idempotency-Key${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - Required: a call without it is refused with '400'. A key of your own that names this one request; a UUID is ideal. It is 8 to 50 characters of letters, digits, '-' and '_'. Send the same key again when you retry (after a timeout, a dropped connection or a '5xx') and the call is carried out once: the retry gets the first answer back, marked 'X-Idempotency-Cached: true'. The same key with a different body is refused with '422', and a retry that arrives while the first call is still running with '409' (see 'Retry-After'). ${YELLOW}Specify as: Idempotency-Key:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}X-Managed-User-Id${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - The id Widgetic gave the managed user ('POST /managed-users'). Makes this call for one of your managed users, so that a mistake in your own code cannot reach another customer's work. Send this header, or the other one, never both. Left out, the call works on your whole account, as it always has. With it, the call reaches only that user's compositions and workflows: a list shows only theirs, a composition or a workflow the call makes is filed under them, and one of another user, or one that does not exist, answers '404' (the same answer, so the call cannot be used to find out what another customer has). A managed user that is not yours answers '404' with 'MANAGED_USER_NOT_FOUND'. An empty, repeated or malformed header is '400' with 'MANAGED_USER_SCOPE_INVALID'; an empty header is never read as no header. A call that is about the whole account, such as the list of your managed users, is refused with '403' and 'MANAGED_USER_SCOPE_ROUTE_NOT_AVAILABLE': send it without the header. Only your API key can send it. The header is a limit the call asks for: whoever holds the key can leave it out, so for a credential that a customer's browser holds, use an editor session. An 'Idempotency-Key' is kept apart for each managed user. ${YELLOW}Specify as: X-Managed-User-Id:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}X-Managed-User-External-Id${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Your own id for the managed user (its 'externalId'), when you do not keep Widgetic's. Makes this call for one of your managed users, so that a mistake in your own code cannot reach another customer's work. Send this header, or the other one, never both. Left out, the call works on your whole account, as it always has. With it, the call reaches only that user's compositions and workflows: a list shows only theirs, a composition or a workflow the call makes is filed under them, and one of another user, or one that does not exist, answers '404' (the same answer, so the call cannot be used to find out what another customer has). A managed user that is not yours answers '404' with 'MANAGED_USER_NOT_FOUND'. An empty, repeated or malformed header is '400' with 'MANAGED_USER_SCOPE_INVALID'; an empty header is never read as no header. A call that is about the whole account, such as the list of your managed users, is refused with '403' and 'MANAGED_USER_SCOPE_ROUTE_NOT_AVAILABLE': send it without the header. Only your API key can send it. The header is a limit the call asks for: whoever holds the key can leave it out, so for a credential that a customer's browser holds, use an editor session. An 'Idempotency-Key' is kept apart for each managed user. ${YELLOW}Specify as: X-Managed-User-External-Id:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}body${OFF} ${BLUE}[application/json]${OFF} ${RED}(required)${OFF}${OFF} - " | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;The data source as it was saved${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;Invalid URL or refresh interval${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;Composition not found${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
##############################################################################
#
# Print help for setDynamicContent operation
#
##############################################################################
print_setDynamicContent_help() {
    echo ""
    echo -e "${BOLD}${WHITE}setDynamicContent - Set Dynamic Content${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo -e "Updates the content of a composition dynamically with optional schema validation.

An editor session (see 'createManagedUserEditorSession') can send only 'content', 'validate' and
'partial', and only for a composition made for its managed user. A body that names 'version', 'source'
or any other field is refused with '403' and 'EDITOR_SESSION_FIELD_NOT_ALLOWED'." | paste -sd' ' | fold -sw 80
    echo -e ""
    echo -e "${BOLD}${WHITE}Parameters${OFF}"
    echo -e "  * ${GREEN}id${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - ID of the composition ${YELLOW}Specify as: id=value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}Idempotency-Key${OFF} ${BLUE}[string]${OFF} ${RED}(required)${OFF} ${CYAN}(default: null)${OFF} - Required: a call without it is refused with '400'. A key of your own that names this one request; a UUID is ideal. It is 8 to 50 characters of letters, digits, '-' and '_'. Send the same key again when you retry (after a timeout, a dropped connection or a '5xx') and the call is carried out once: the retry gets the first answer back, marked 'X-Idempotency-Cached: true'. The same key with a different body is refused with '422', and a retry that arrives while the first call is still running with '409' (see 'Retry-After'). ${YELLOW}Specify as: Idempotency-Key:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}If-Match${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Optional content version from ETag ('\"3\"', '3', or '*') ${YELLOW}Specify as: If-Match:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}X-Managed-User-Id${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - The id Widgetic gave the managed user ('POST /managed-users'). Makes this call for one of your managed users, so that a mistake in your own code cannot reach another customer's work. Send this header, or the other one, never both. Left out, the call works on your whole account, as it always has. With it, the call reaches only that user's compositions and workflows: a list shows only theirs, a composition or a workflow the call makes is filed under them, and one of another user, or one that does not exist, answers '404' (the same answer, so the call cannot be used to find out what another customer has). A managed user that is not yours answers '404' with 'MANAGED_USER_NOT_FOUND'. An empty, repeated or malformed header is '400' with 'MANAGED_USER_SCOPE_INVALID'; an empty header is never read as no header. A call that is about the whole account, such as the list of your managed users, is refused with '403' and 'MANAGED_USER_SCOPE_ROUTE_NOT_AVAILABLE': send it without the header. Only your API key can send it. The header is a limit the call asks for: whoever holds the key can leave it out, so for a credential that a customer's browser holds, use an editor session. An 'Idempotency-Key' is kept apart for each managed user. ${YELLOW}Specify as: X-Managed-User-Id:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}X-Managed-User-External-Id${OFF} ${BLUE}[string]${OFF} ${CYAN}(default: null)${OFF} - Your own id for the managed user (its 'externalId'), when you do not keep Widgetic's. Makes this call for one of your managed users, so that a mistake in your own code cannot reach another customer's work. Send this header, or the other one, never both. Left out, the call works on your whole account, as it always has. With it, the call reaches only that user's compositions and workflows: a list shows only theirs, a composition or a workflow the call makes is filed under them, and one of another user, or one that does not exist, answers '404' (the same answer, so the call cannot be used to find out what another customer has). A managed user that is not yours answers '404' with 'MANAGED_USER_NOT_FOUND'. An empty, repeated or malformed header is '400' with 'MANAGED_USER_SCOPE_INVALID'; an empty header is never read as no header. A call that is about the whole account, such as the list of your managed users, is refused with '403' and 'MANAGED_USER_SCOPE_ROUTE_NOT_AVAILABLE': send it without the header. Only your API key can send it. The header is a limit the call asks for: whoever holds the key can leave it out, so for a credential that a customer's browser holds, use an editor session. An 'Idempotency-Key' is kept apart for each managed user. ${YELLOW}Specify as: X-Managed-User-External-Id:value${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e "  * ${GREEN}body${OFF} ${BLUE}[application/json]${OFF} ${RED}(required)${OFF}${OFF} - " | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
    echo ""
    echo -e "${BOLD}${WHITE}Responses${OFF}"
    code=200
    echo -e "${result_color_table[${code:0:1}]}  200;Content updated successfully${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
        echo -e "       ${BOLD}${WHITE}Response headers${OFF}"
        echo -e "       ${BLUE}ETag${OFF} - Quoted content version for the next If-Match" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/        /'
    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;Invalid content, validation failed, or invalid If-Match${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=401
    echo -e "${result_color_table[${code:0:1}]}  401;Unauthorized${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=403
    echo -e "${result_color_table[${code:0:1}]}  403;Not allowed - an editor session named a field it may not write ('EDITOR_SESSION_FIELD_NOT_ALLOWED')${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;Composition not found${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=409
    echo -e "${result_color_table[${code:0:1}]}  409;Content write conflict without If-Match ('CONTENT_WRITE_CONFLICT'): another save of the same composition got in
between. For a composition a team shares 'error.details' says who made the latest change
('lastEditedBy', 'lastEditedAt'), to a person only.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=412
    echo -e "${result_color_table[${code:0:1}]}  412;Content version mismatch ('CONTENT_VERSION_MISMATCH'). 'error.details.currentVersion' is the version to start
again from. For a composition a team shares 'error.details.lastEditedBy' ('{ id, name }', or
'null' when nobody can be named) and 'error.details.lastEditedAt' say who saved first and when. An editor
session, or a call made for one managed user, is told the version only.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=503
    echo -e "${result_color_table[${code:0:1}]}  503;Content version unavailable ('CONTENT_VERSION_UNAVAILABLE') when If-Match was sent before migration${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
