    echo -e "${result_color_table[${code:0:1}]}  404;No such upload on this account ('UPLOAD_NOT_FOUND')${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
}
