    code=404
    echo -e "${result_color_table[${code:0:1}]}  404;There is no such partner (reported to administrators only), or no managed user of yours matches (MANAGED_USER_NOT_FOUND)${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
