    code=503
    echo -e "${result_color_table[${code:0:1}]}  503;Widgetic could not check what the database holds (PARTNER_DATABASE_UNAVAILABLE). Nothing was changed.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
