    code=429
    echo -e "${result_color_table[${code:0:1}]}  429;Too many changes in a short time. Try again after the Retry-After seconds.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
    code=503
    echo -e "${result_color_table[${code:0:1}]}  503;Webhooks cannot be set up on this server right now (WEBHOOK_SIGNING_UNAVAILABLE). Nothing was changed.${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
