    echo ""
    echo -e "${BOLD}${WHITE}restoreWorkspaceWorkflowVersion_0 - Restore a Version of a Workflow into the Draft${OFF}${BLUE}(AUTH - )${OFF}" | paste -sd' ' | fold -sw 80 | sed '2,$s/^/    /'
    echo -e ""
