    code=400
    echo -e "${result_color_table[${code:0:1}]}  400;Nothing to save, or the name, the time zone or the shape of the graph is not acceptable${OFF}" | paste -sd' ' | column -t -s ';' | fold -sw 80 | sed '2,$s/^/       /'
